# Pictures for the pe library (read with ast.literal_eval; never run).
# The examples run through TB on two tiny demo files written from the hex
# below: demo.exe (a 64-bit program importing injection and network calls)
# and demo.dll (exporting three functions). They are made by
# tests/binfixtures.py and contain no real code.
SPEC = {
    "_default": {"imports": ["binary", "fs"], "setup": 'let exe = binary.from_hex("")\nfs.write_bytes("demo.exe", exe)\nfs.write_bytes("demo.dll", binary.from_hex(""))', "modes": {"path": "lines"}},
    "parse": {
        "args": {"path": '"demo.exe"'},
        "keys": ["format", "architecture", "subsystem", "compiled", "entry_section", "import_count", "is_signed"],
        "nodes": [{"param": "path", "icon": "file", "lines": ["demo.exe", "MZ \u2026 PE\\0\\0 \u2026 4 sections"]},
                  {"arrow": "pe.parse"}, {"result": True, "label": "result \u00b7 everything pe knows (some keys shown)"}],
        "roles": {"path": "a Windows .exe, .dll or .sys file"},
    },
    "parse_bytes": {
        "args": {"data": "exe"},
        "keys": ["format", "architecture", "is_dll", "entry_hex"],
        "nodes": [{"param": "data", "icon": "cpu", "lines": ["bytes in memory", "4d 5a 90 00 \u2026 (MZ)"]},
                  {"arrow": "pe.parse_bytes"}, {"result": True, "label": "result \u00b7 the same map as parse()"}],
        "roles": {"data": "the file's bytes, already read (from a capture, an archive...)"},
    },
    "is_pe": {
        "args": {"path": '"demo.exe"'},
        "vary": {"param": "path", "values": ['"demo.exe"', '"notes.txt"'], "labels": ["demo.exe", "notes.txt"]},
        "roles": {"path": "the file to check: MZ header and PE signature"},
    },
    "sections": {
        "args": {"path": '"demo.exe"'},
        "keys": ["name", "size", "entropy", "flags"],
        "nodes": [{"param": "path", "icon": "file"}, {"arrow": "pe.sections"},
                  {"result": True, "label": "result \u00b7 code, data and import sections"}],
        "roles": {"path": "the PE file"},
    },
    "imports": {
        "args": {"path": '"demo.exe"'},
        "mode": "tree",
        "nodes": [{"param": "path", "icon": "file"}, {"arrow": "pe.imports"},
                  {"result": True, "label": "result \u00b7 DLL name -> functions it calls", "mode": "tree"}],
        "roles": {"path": "the PE file"},
    },
    "exports": {
        "args": {"path": '"demo.dll"'},
        "nodes": [{"param": "path", "icon": "file"}, {"arrow": "pe.exports"},
                  {"result": True, "label": "result \u00b7 what the DLL offers"}],
        "vary": {"param": "path", "values": ['"demo.dll"', '"demo.exe"'], "labels": ["demo.dll", "demo.exe (none)"]},
        "roles": {"path": "the PE file (usually a DLL)"},
    },
    "indicators": {
        "args": {"path_or_info": '"demo.exe"'},
        "keys": ["level", "name"],
        "nodes": [{"param": "path_or_info", "icon": "file", "mode": "lines"},
                  {"box": "checks", "icon": "shield", "lines": ["injection APIs? packed? ASLR, DEP?", "signed? entry point odd?"]},
                  {"arrow": "pe.indicators"}, {"result": True, "label": "result \u00b7 suspicious things, most serious first"}],
        "roles": {"path_or_info": "a file path, or the map pe.parse() gave"},
    },
    "summary": {
        "args": {"path": '"demo.exe"'},
        "mode": "lines",
        "nodes": [{"param": "path", "icon": "file"}, {"arrow": "pe.summary"}, {"result": True, "label": "result \u00b7 one line for a report"}],
        "roles": {"path": "the PE file"},
    },
}
